	private static final String DECLINE = "optimizer.frontierSemanticPopulation";

	@Test
	void exactFitRetainsPayloadButOneByteShortStripsItWithoutInventingSemanticEvidence() {
		Fixture fixture = fixture(contract(new Payload(1_024L)), "spoc");
		PackedOptimizationDecision decision = decision(fixture);
		long exactBytes = decision.retainedBytes();
		assertTrue(exactBytes >= 1_024L);
		PackedPlanCache.PlanEntry exact = publish(new PackedPlanCache(4, 1, exactBytes), fixture, decision);
		assertSame(fixture.contract, exact.recipe().runtimeFeedbackContract(exact.recipe().rootRecipeId()));
		assertTrue(exact.optimizationDecision().hasRetainedProviderPayload());
		assertFalse(exact.supportsStaleValidation(), "a physical payload cannot stand in for semantic evidence");
		PackedPlanCache.PlanEntry shortEntry = publish(new PackedPlanCache(4, 1, exactBytes - 1L), fixture, decision);
		assertStripped(shortEntry.recipe());
		assertFalse(shortEntry.optimizationDecision().hasRetainedProviderPayload());
		assertSame(fixture.contract, fixture.recipe.runtimeFeedbackContract(fixture.recipe.rootRecipeId()),
				"refusal must copy the recipe instead of mutating an already returned decision");
	}

	@Test
	void nonChampionPayloadUsesTheSameBudgetAndSharedPayloadIsAccountedOnce() {
		Payload payload = new Payload(2_048L);
		Fixture plain = fixture(null, "spoc");
		Fixture first = fixture(contract(payload), "posc");
		Fixture second = fixture(contract(payload), "ospc");
		PackedOptimizationDecision shared = new PackedOptimizationDecision(null,
				new PackedOptimizationDecision.Candidate[] { candidate(plain), candidate(first), candidate(second) },
				PackedSearchCompletionStatus.EXACT_COMPLETE, 3L);
		PackedProviderRetainedMemory scope = new PackedProviderRetainedMemory();
		first.recipe.detachedProviderBytes(scope);
		long before = scope.bytes();
		second.recipe.detachedProviderBytes(scope);
		long sharedDelta = scope.bytes() - before;
		Fixture different = fixture(contract(new Payload(2_048L)), "ospc");
		PackedProviderRetainedMemory unshared = new PackedProviderRetainedMemory();
		first.recipe.detachedProviderBytes(unshared);
		before = unshared.bytes();
		different.recipe.detachedProviderBytes(unshared);
		assertEquals(sharedDelta + 2_048L, unshared.bytes() - before);
		assertTrue(shared.hasRetainedProviderPayload());
		assertFalse(plain.recipe.hasRetainedProviderPayload());
		PackedPlanCache.PlanEntry stripped = publish(new PackedPlanCache(4, 1, 0L), plain, shared);
		assertFalse(stripped.optimizationDecision().hasRetainedProviderPayload());
		PackedQueryFamilyIdentity family = PackedQueryFamilyIdentity.create(plain.source, null);
		assertNoPayload(stripped.optimizationDecision().materializeCandidate(1, family));
		assertNoPayload(stripped.optimizationDecision().materializeCandidate(2, family));
		assertNull(plain.recipe.runtimeFeedbackContract(plain.recipe.rootRecipeId()));
	}

	@Test
	void replacedChampionDoesNotLeaveItsIndependentCheckpointPayloadOutsideTheBudget() {
		Fixture old = fixture(contract(new Payload(4_096L)), "spoc");
		Fixture fresh = fixture(null, "spoc");
		PackedQueryFamilyIdentity family = PackedQueryFamilyIdentity.create(old.source, null);
		PackedOptimizationDecision original = new PackedOptimizationDecision(family,
				new PackedOptimizationDecision.Candidate[] { candidate(old) },
				PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT, 17L).withFamilyIdentity(family);
		PackedOptimizationDecision replaced = original.withChampion(fresh.recipe, 2.0d);
		assertFalse(fresh.recipe.hasRetainedProviderPayload());
		assertTrue(replaced.hasRetainedProviderPayload());
		assertSame(old.recipe, replaced.searchCheckpoint().continuationRecipe());
		long accounted = replaced.retainedBytes();
		PackedOptimizationDecision stripped = replaced.withoutDetachedEvidence();
		assertFalse(stripped.hasRetainedProviderPayload());
		assertStripped(stripped.searchCheckpoint().continuationRecipe());
		assertTrue(accounted > stripped.retainedBytes());
		assertEquals(original.searchCheckpoint().phase(), stripped.searchCheckpoint().phase());
		assertEquals(original.searchCheckpoint().completionStatus(), stripped.searchCheckpoint().completionStatus());
		assertEquals(17L, stripped.searchCheckpoint().cumulativeWorkUnits());
		assertTrue(stripped.searchCheckpoint().matches(family));
		assertSame(old.contract, original.searchCheckpoint()
				.continuationRecipe()
				.runtimeFeedbackContract(old.recipe.rootRecipeId()));
	}

