		long budget = Math.max(decision(first).retainedBytes(), decision(next).retainedBytes());
		PackedPlanCache cache = new PackedPlanCache(8, 1, budget);
		publish(cache, first, decision(first));
		// A different data revision retains both exact plan entries in one segment but permits only one payload.
		PackedPlanCache.Context newer = context(2L);
