	@Test
	void realPlannerPublicationReplayAndNewGenerationNeverAddAnUnchargedPayloadOwner() {
		PackedPlanCache cache = new PackedPlanCache(8, 1, 0L);
		TupleExpr source = source();
		RuntimeFeedbackContract previous = contract(new Payload(8_192L));
		source.setRuntimeFeedbackContract(previous);
		source.setStringMetricPlanned(DECLINE, "unavailable");
		AtomicInteger callbacks = new AtomicInteger();
		PackedCostModel model = model(previous, callbacks);
		PackedPlanningResult cold = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache,
				context(1L), model);
		assertTrue(cold.exactComplete());
		assertTrue(callbacks.get() > 0);
		PackedPlanCache.PlanEntry entry = cache.findPlan(cache.fingerprint(source), context(1L), source);
		assertNotNull(entry);
		assertStripped(entry.recipe());
		int initialCalls = callbacks.get();
		PackedPlanningResult hot = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache,
				context(1L), model);
		assertTrue(hot.metrics().planCacheHit());
		assertEquals(initialCalls, callbacks.get());
		assertNoPayload(hot.selectedPlan());
		RuntimeFeedbackContract next = contract(new Payload(16_384L));
		PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), cache, context(2L), model(next, callbacks));
		assertTrue(callbacks.get() > initialCalls);
		PackedPlanCache.PlanEntry updated = cache.findPlan(cache.fingerprint(source), context(2L), source);
		assertStripped(updated.recipe());
		assertNoPayload(PackedPlanMaterializer.materialize(updated.query(), updated.recipe()));
		assertSame(previous, source.getRuntimeFeedbackContract(), "caller source remains immutable");
	}

