		PackedPlanRefreshWork work = new PackedPlanRefreshWork(source,
				OptimizationGoal.root(source, PhysicalProperties.ANY),
				new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE, PackedPlannerLimits.DEFAULT_MAX_RETAINED_BYTES),
				PackedPlanCache.structuralKey(source), "incumbent");
