	@Test
	void admittedThenEvidenceRetiredFutureDropsCandidateAndDistinctContinuationPayloads() {
		FutureFixture first = futureFixture(PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT);
		Fixture next = fixture(contract(new Payload(4_096L)), "ospc");
		long budget = Math.max(first.decision.retainedBytes(), decision(next).retainedBytes());
		PackedPlanCache cache = new PackedPlanCache(8, 1, budget);
		Publication published = beginPublication(cache, first.fixture, first.decision, context(1L),
				new PackedPlannerLimits(17L, Long.MAX_VALUE, PackedPlannerLimits.DEFAULT_MAX_RETAINED_BYTES));
		cache.publish(published.owner, published.input, published.queryEntry);
		PackedPlanCache.PlanEntry admitted = cache.findPlan(cache.fingerprint(first.fixture.source), context(1L),
				first.fixture.source, PackedQueryCacheIdentity.createPlanIdentity(first.fixture.source),
				published.limits);
		assertNotNull(admitted);
		assertTrue(admitted.optimizationDecision().hasRetainedProviderPayload());
		assertSame(first.continuation.recipe, admitted.optimizationDecision().searchCheckpoint().continuationRecipe());
		// Leave the waiter suspended across a real evidence-cap retirement that refunds this stored payload.
		publish(cache, next, decision(next), context(2L));
		PackedPlanCache.PlanEntry retired = cache.findPlan(cache.fingerprint(first.fixture.source), context(1L),
				first.fixture.source, PackedQueryCacheIdentity.createPlanIdentity(first.fixture.source),
				published.limits);
		assertNotNull(retired);
		assertFalse(retired.optimizationDecision().hasRetainedProviderPayload());
		assertNotSame(admitted, retired);
		assertSanitizedDisposition(published.input, published.waiter.await(), first.family);
		assertFutureCallerIntact(first, published.input);
	}

	@Test
	void admittedThenReplacedFutureDoesNotKeepTheRefundedOldDecision() {
		FutureFixture first = futureFixture(PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT);
		Fixture next = fixture(contract(new Payload(4_096L)), "ospc");
		PackedPlanCache cache = new PackedPlanCache(1, 1,
				Math.max(first.decision.retainedBytes(), decision(next).retainedBytes()));
		Publication published = beginPublication(cache, first.fixture, first.decision, context(1L),
				new PackedPlannerLimits(17L, Long.MAX_VALUE, PackedPlannerLimits.DEFAULT_MAX_RETAINED_BYTES));
		cache.publish(published.owner, published.input, published.queryEntry);
		assertTrue(cache.findPlan(cache.fingerprint(first.fixture.source), context(1L), first.fixture.source,
				PackedQueryCacheIdentity.createPlanIdentity(first.fixture.source), published.limits)
				.optimizationDecision()
				.hasRetainedProviderPayload());
		// The public cache normalizes one requested slot to two. Fill its actual second slot, then
		// keep that filler hotter so the existing victim policy replaces the first published entry.
		Fixture filler = fixture(null, "posc");
		publish(cache, filler, decision(filler), context(3L));
		assertNotNull(cache.findPlan(cache.fingerprint(filler.source), context(3L), filler.source));
		assertNotNull(cache.findPlan(cache.fingerprint(filler.source), context(3L), filler.source));
		publish(cache, next, decision(next), context(2L));
		assertNull(cache.findPlan(cache.fingerprint(first.fixture.source), context(1L), first.fixture.source,
				PackedQueryCacheIdentity.createPlanIdentity(first.fixture.source), published.limits));
		assertTrue(cache.findPlan(cache.fingerprint(next.source), context(2L), next.source)
				.optimizationDecision()
				.hasRetainedProviderPayload());
		assertSanitizedDisposition(published.input, published.waiter.await(), first.family);
		assertFutureCallerIntact(first, published.input);
	}

